```python
def max_sum(arr):
    n=len(arr); inc=list(arr); dec=inc[:]
    for i in range(n):
        for j in range(i):
            if arr[j]<arr[i]: inc[i]=max(inc[i],inc[j]+arr[i])
    for i in range(n-1,-1,-1):
        for j in range(i+1,n):
            if arr[j]<arr[i]: dec[i]=max(dec[i],dec[j]+arr[i])
    return max(x+y-z for x,y,z in zip(inc,dec,arr))
```
